#pragma once
#include "Configuration.h"
#include "SerialMessage.hpp"
#include "FastAccelStepper.h"

// 步进电机：STEP 脉冲由 FastAccelStepper 产生，本文件只负责"收命令 → 起运动 → 停运动"。
//
// 控制通道只有一条队列。队列里的命令只可能是三种：
//   ACTION_POSITION     定量走，走完自己停
//   ACTION_CONTINUOUS   以给定速度持续走，直到 ACTION_STOP
//   ACTION_STOP         停止
// 同一时刻只允许一个动作，运动中收到新的定量/持续命令一律拒绝（不排队、不覆盖）；
// 只有 ACTION_STOP 可以打断正在执行的命令，也可以取消还在队列里没启动的命令。
//
// The STEP pulse train is generated by FastAccelStepper. The only control channel
// is the command queue: ACTION_POSITION (fixed step count), ACTION_CONTINUOUS
// (run at a given speed until stopped) and ACTION_STOP. A move/run command is
// rejected while another action is in progress; only ACTION_STOP may interrupt it.

// State Machine
enum StepperState
{
    STEPPER_IDLE,
    STEPPER_RUNNING
};

enum MoveAction
{
    ACTION_POSITION,   // 有限步数
    ACTION_CONTINUOUS, // 持续运行
    ACTION_STOP        // 停止
};

enum StepperDirection
{
    DIR_WORK,
    DIR_INIT
};

struct MoveCommand
{
    MoveAction action;
    StepperDirection dir;
    uint32_t pulse_count;
    uint32_t delay_us;
    bool tracking;
};

uint32_t Pulse_RA(float azimuth);
uint32_t Pulse_DEC(float altitude);

bool Is_Stepper_RA_running();
bool Is_Stepper_DEC_running();

bool Stepper_RA_SendCommand(const MoveCommand &cmd);
bool Stepper_DEC_SendCommand(const MoveCommand &cmd);

void Stepper_RA_Stop();
void Stepper_DEC_Stop();

void set_Stepper_RA_running(bool state);
void set_Stepper_DEC_running(bool state);

// 创建队列、初始化引擎并把两轴接到各自的 STEP/DIR 引脚，必须先于两个步进任务调用
void InitCelestialStepper();

void task_Stepper_RA(void *parameters);
void task_Stepper_DEC(void *parameters);

// ===========================================================================
// 每轴一份参数 + 一份运行时上下文，两轴共用同一套代码
// ===========================================================================

struct StepperConfig
{
    uint8_t stepPin;
    uint8_t dirPin;
    uint8_t dirLevelInit; // DIR_INIT 对应的 DIR 引脚电平
    uint8_t dirLevelWork; // DIR_WORK 对应的 DIR 引脚电平
    uint32_t halfPeriodUs;
    uint32_t acceleration;
    const char *name;
};

struct StepperAxis
{
    const StepperConfig *cfg;
    FastAccelStepper *handle;
    QueueHandle_t queue;
    volatile bool running; // 有命令正在执行
};

static const StepperConfig stepperConfig_RA = {
    Pin_Stepper_RA_Step, Pin_Stepper_RA_Dir,
    Stepper_RA_Initialize_Dir, Stepper_RA_Work_Dir,
    Stepper_RA_StepHalfPeriodUs, Stepper_RA_Acceleration, "RA"};

static const StepperConfig stepperConfig_DEC = {
    Pin_Stepper_DEC_Step, Pin_Stepper_DEC_Dir,
    Stepper_DEC_Initialize_Dir, Stepper_DEC_Work_Dir,
    Stepper_DEC_StepHalfPeriodUs, Stepper_DEC_Acceleration, "DEC"};

static StepperAxis axis_RA = {&stepperConfig_RA, NULL, NULL, false};
static StepperAxis axis_DEC = {&stepperConfig_DEC, NULL, NULL, false};

// FastAccelStepper 引擎接管 STEP/DIR 引脚，脉冲由硬件定时器产生
FastAccelStepperEngine stepperEngine;

// 相对位置偏移运动量计算

uint32_t Pulse_RA(float ra)
{
    // TODO Depend on Mechanical structure reduction ratio coefficient
    return (uint32_t)(ra * Stepper_RA_K);
}

uint32_t Pulse_DEC(float dec)
{
    // TODO Depend on Mechanical structure reduction ratio coefficient
    return (uint32_t)(dec * Stepper_DEC_K);
}

// ===========================================================================
// 内部实现
// ===========================================================================

// 原来一个 STEP 脉冲是"高 P µs + 低 P µs"，整步周期为 2*P
static uint32_t Stepper_StepPeriodUs(uint32_t halfPeriodUs)
{
    const uint32_t kMaxPeriodUs = 4000000UL; // 防止 2*P 溢出，也超出库的 tick 表示范围
    if (halfPeriodUs > (kMaxPeriodUs / 2))
    {
        return kMaxPeriodUs;
    }
    const uint32_t periodUs = halfPeriodUs * 2;
    return (periodUs == 0) ? 1 : periodUs;
}

// DIR_INIT / DIR_WORK 是 DIR 引脚电平的两种约定，这里换算成步进方向的正负号。
// setDirectionPin(pin, true) 约定计数向上时 DIR 输出 HIGH。
static int32_t Stepper_Sign(const StepperAxis &axis, StepperDirection dir)
{
    const uint8_t level = (dir == DIR_INIT) ? axis.cfg->dirLevelInit : axis.cfg->dirLevelWork;
    return (level == HIGH) ? 1 : -1;
}

// 构造一条停止命令
static MoveCommand Stepper_StopCommand()
{
    return MoveCommand{ACTION_STOP, DIR_WORK, 0, 0, false};
}

// 队列里如果挂着停止命令就取走；其他命令原样留在队列里（它们属于下一条动作）
static bool Stepper_TakeStop(StepperAxis &axis)
{
    MoveCommand cmd;
    if (xQueuePeek(axis.queue, &cmd, (TickType_t)0) != pdPASS || cmd.action != ACTION_STOP)
    {
        return false;
    }
    xQueueReceive(axis.queue, &cmd, (TickType_t)0);
    return true;
}

// 急停：立刻断开脉冲输出，队列里已排好的脉冲一律作废。
//
// 这里必须用 forceStopAndNewPosition() 而不是 forceStop()：
//   forceStop()             只是不再投喂新命令，队列里的脉冲还会继续走完（约 20 ms），
//                           对"持续运行"来说就是停不下来；
//   forceStopAndNewPosition 直接关掉 RMT/I2S 通道并清空队列，官方注释写明
//                           "No further step will be issued"，且执行是同步的。
// 代价是精确停位无法在中断里恢复，所以把当前位置原样写回去（本项目不做绝对定位）。
// 它也不会留下 immediate-stop 锁存，后续的 move()/runForward() 不会被吞掉。
static void Stepper_Halt(StepperAxis &axis)
{
    if (axis.handle != NULL && axis.handle->isRunning())
    {
        axis.handle->forceStopAndNewPosition(axis.handle->getCurrentPosition());
    }
}

// 等本段运动结束；返回 true 表示收到停止命令。
// 停止命令先入队、后断硬件，所以 isRunning() 变 false 时停止命令一定已经在队列里；
// 这里先查队列再查 isRunning()，不会把急停误判成"自然走完"。
static bool Stepper_WaitDone(StepperAxis &axis)
{
    for (;;)
    {
        if (Stepper_TakeStop(axis))
        {
            return true;
        }
        if (!axis.handle->isRunning())
        {
            return false;
        }
        vTaskDelay((TickType_t)1); // 1 ms 轮询，停止命令的响应延迟不超过一个 tick
    }
}

// 起一段有限步数的运动
static void Stepper_StartMove(StepperAxis &axis, int32_t sign, uint32_t steps, uint32_t halfPeriodUs)
{
    if (steps > 0x7FFFFFFFUL) // int32 上限，避免符号翻转
    {
        steps = 0x7FFFFFFFUL;
    }
    axis.handle->setSpeedInUs(Stepper_StepPeriodUs(halfPeriodUs));
    axis.handle->setAcceleration(axis.cfg->acceleration);
    axis.handle->move(sign * (int32_t)steps);
}

// 起一段持续运动
static void Stepper_StartRun(StepperAxis &axis, int32_t sign, uint32_t halfPeriodUs)
{
    axis.handle->setSpeedInUs(Stepper_StepPeriodUs(halfPeriodUs));
    axis.handle->setAcceleration(axis.cfg->acceleration);
    if (sign > 0)
    {
        axis.handle->runForward();
    }
    else
    {
        axis.handle->runBackward();
    }
}

// 执行一条动作命令：先按需走定位段，再按需进入连续段。
static void Stepper_ExecCommand(StepperAxis &axis, const MoveCommand &cmd)
{
    if (axis.handle == NULL)
    {
        return;
    }

    const int32_t sign = Stepper_Sign(axis, cmd.dir);

    // 定位段：ACTION_POSITION 的固定脉冲数（速度沿用配置里的固定半周期）
    if (cmd.action == ACTION_POSITION && cmd.pulse_count > 0)
    {
        Stepper_StartMove(axis, sign, cmd.pulse_count, axis.cfg->halfPeriodUs);
        if (Stepper_WaitDone(axis))
        {
            // 定位途中被停止：确保停住，并且不再进入跟踪段
            Stepper_Halt(axis);
            return;
        }
    }

    // 连续段：ACTION_CONTINUOUS，或定位完成后的跟踪（速度用命令里的 delay_us）
    if (cmd.action == ACTION_CONTINUOUS || (cmd.action == ACTION_POSITION && cmd.tracking))
    {
        if (Stepper_TakeStop(axis))
        {
            // 定位段刚走完就来了停止，不要再把连续段拉起来
            return;
        }
        Stepper_StartRun(axis, sign, cmd.delay_us);
        if (Stepper_WaitDone(axis))
        {
            Stepper_Halt(axis);
        }
    }
}

// 停止：入队 + 同步断硬件。入队必须在断硬件之前，见 Stepper_WaitDone 的说明。
static void Stepper_RequestStop(StepperAxis &axis)
{
    if (axis.queue != NULL)
    {
        MoveCommand stopCmd = Stepper_StopCommand();
        // 队列长度是 1，用 overwrite 保证停止永远能进去，并顺带取消还没启动的命令
        xQueueOverwrite(axis.queue, &stopCmd);
    }
    Stepper_Halt(axis);
}

static bool Stepper_Send(StepperAxis &axis, const MoveCommand &cmd)
{
    if (axis.queue == NULL)
    {
        return false;
    }
    if (cmd.action == ACTION_STOP)
    {
        Stepper_RequestStop(axis); // 停止永远接受
        return true;
    }
    if (axis.running)
    {
        // 已有动作在执行：不排队、不覆盖
        return false;
    }
    return xQueueSend(axis.queue, &cmd, (TickType_t)0) == pdPASS;
}

static void Stepper_InitAxis(StepperAxis &axis)
{
    axis.queue = xQueueCreate(1, sizeof(MoveCommand));

    axis.handle = stepperEngine.stepperConnectToPin(axis.cfg->stepPin);
    if (axis.handle == NULL)
    {
        Serial0_Printf("FastAccelStepper: connect %s stepper failed!", axis.cfg->name);
        return;
    }
    axis.handle->setDirectionPin(axis.cfg->dirPin, true);
    axis.handle->setLinearAcceleration(0); // 线性加速段为 0，起停轮廓与原来一样"直起直停"
    axis.handle->setSpeedInUs(Stepper_StepPeriodUs(axis.cfg->halfPeriodUs));
    axis.handle->setAcceleration(axis.cfg->acceleration);
}

// 两轴共用的任务体
static void Stepper_TaskMain(StepperAxis &axis)
{
    if (axis.queue == NULL)
    {
        Serial0_Printf("Stepper %s: queue is NULL, call InitCelestialStepper() first!", axis.cfg->name);
        vTaskDelete(NULL);
        return;
    }

    MoveCommand cmd;
    for (;;)
    {
        if (xQueueReceive(axis.queue, &cmd, portMAX_DELAY) != pdPASS)
        {
            continue;
        }
        if (cmd.action == ACTION_STOP)
        {
            // 空闲时收到停止：硬件已经在 Stepper_RequestStop() 里停过了，这里什么都不用做。
            // 注意不是"留着下次用"——留到下一条命令会把它吃掉。
            continue;
        }

        axis.running = true;
        Stepper_ExecCommand(axis, cmd);
        axis.running = false;
    }
}

// ===========================================================================
// 对外接口
// ===========================================================================

// 创建队列、初始化引擎并接好两轴。必须在 xTaskCreate 两个步进任务之前调用。
void InitCelestialStepper()
{
    static bool initialized = false;
    if (initialized)
    {
        return;
    }
    initialized = true;

    stepperEngine.init();
    Stepper_InitAxis(axis_RA);
    Stepper_InitAxis(axis_DEC);
}

// configMAX_PRIORITIES - 3
void task_Stepper_RA(void *parameters)
{
    Stepper_TaskMain(axis_RA);
}

// configMAX_PRIORITIES - 3
void task_Stepper_DEC(void *parameters)
{
    Stepper_TaskMain(axis_DEC);
}

bool Is_Stepper_RA_running()
{
    return axis_RA.running;
}
bool Is_Stepper_DEC_running()
{
    return axis_DEC.running;
}

void set_Stepper_RA_running(bool state)
{
    axis_RA.running = state;
}
void set_Stepper_DEC_running(bool state)
{
    axis_DEC.running = state;
}

bool Stepper_RA_SendCommand(const MoveCommand &cmd)
{
    return Stepper_Send(axis_RA, cmd);
}
bool Stepper_DEC_SendCommand(const MoveCommand &cmd)
{
    return Stepper_Send(axis_DEC, cmd);
}

void Stepper_RA_Stop()
{
    Stepper_RequestStop(axis_RA);
}
void Stepper_DEC_Stop()
{
    Stepper_RequestStop(axis_DEC);
}
